use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn count_unival_subtrees(root:Option<Rc<RefCell<TreeNode>>>)->i32{fn f(n:&Option<Rc<RefCell<TreeNode>>>,c:&mut i32)->bool{if let Some(x)=n{let b=x.borrow();let l=f(&b.left,c);let r=f(&b.right,c);if !l||!r{return false}if let Some(y)=&b.left{if y.borrow().val!=b.val{return false}}if let Some(y)=&b.right{if y.borrow().val!=b.val{return false}}*c+=1;true}else{true}}let mut c=0;f(&root,&mut c);c}}
